import { Image } from "@/components/common/image";
import { Richtext } from "@/components/common/richtext";
import { getSectionAppearance } from "@/components/common/section-appearance";
import Container from "@/components/ui/Container";
import type { SlidersSection } from "../types";
import styles from "./style.module.css";

const SCROLL_FROM_SLIDE_COUNT = 7;

const CARD_CLASS =
  "h-[80px] w-[113px] items-center justify-center overflow-hidden rounded-[10px] lg:h-[138px] lg:w-[223px] lg:rounded-[20px]";
const LOGO_CLASS =
  "h-auto w-auto max-h-[33px] max-w-[84px] object-contain lg:max-h-[65px] lg:max-w-[170px]";
const CELL_CLASS = "shrink-0 mr-[10px] lg:mr-[20px]";

type LogoSlideData = NonNullable<SlidersSection["slides"]>[number];

/**
 * A slide is a Logo Item entry: one logo plus that entry's own link behaviour.
 * "None" — and a link behaviour whose target field was left empty — renders the
 * card with no anchor.
 */
function slideHref(slide: LogoSlideData): string | undefined {
  if (slide.linkBehaviour === "Internal Link") return slide.internalPage?.url ?? undefined;
  if (slide.linkBehaviour === "External Link") return slide.externalUrl ?? undefined;
  return undefined;
}

/** `decorative` marks the duplicated marquee copy, which is aria-hidden and so
 *  must never hold a focusable link. */
function LogoCard({ slide, decorative = false }: { slide: LogoSlideData; decorative?: boolean }) {
  const card = (
    <div className={["flex flex-col", CARD_CLASS, "bg-cream"].join(" ")}>
      {slide.logo ? <Image section={slide.logo} className={LOGO_CLASS} /> : null}
    </div>
  );

  const href = decorative ? undefined : slideHref(slide);
  if (!href) return card;

  const newTab = Boolean(slide.openInNewTab);

  return (
    <a
      className="block"
      href={href}
      target={newTab ? "_blank" : undefined}
      rel={newTab ? "noopener noreferrer" : undefined}
    >
      {card}
    </a>
  );
}

export function LogoSlider({ section }: { section: SlidersSection }) {
  const slides = section.slides ?? [];
  const headline = section.headline;

  if (!headline && slides.length === 0) return null;

  const isScrolling = slides.length >= SCROLL_FROM_SLIDE_COUNT;
  const { spacingClasses, containerType } = getSectionAppearance(section.sectionAppearance);

  return (
    <section
      data-section="sliders"
      data-variant="Logo Slider"
      className={`bg-white ${spacingClasses}`}
    >
      {headline ? (
        <Container type={containerType}>
          <div className="mx-auto mb-m max-w-[953px] text-center lg:mb-[89px]">
            <Richtext field={headline} />
          </div>
        </Container>
      ) : null}

      {slides.length === 0 ? null : isScrolling ? (
        <div className="overflow-hidden">
          <ul className={`${styles.track} flex w-max items-center`}>
            {slides.map((slide, index) => (
              <li key={slide.sys?.id ?? `logo-${index}`} className={CELL_CLASS}>
                <LogoCard slide={slide} />
              </li>
            ))}
            {slides.map((slide, index) => (
              <li
                key={`loop-${slide.sys?.id ?? index}`}
                className={CELL_CLASS}
                aria-hidden="true"
              >
                <LogoCard slide={slide} decorative />
              </li>
            ))}
          </ul>
        </div>
      ) : (
        <Container type={containerType}>
          <ul className="flex flex-wrap items-center justify-center gap-4xs lg:gap-2xs">
            {slides.map((slide, index) => (
              <li key={slide.sys?.id ?? `logo-${index}`} className="shrink-0">
                <LogoCard slide={slide} />
              </li>
            ))}
          </ul>
        </Container>
      )}
    </section>
  );
}

