// Generated by Foundry v3 wiring. Edit the wiring spec, then regenerate.
/** Shared by the live wiring probe and generated page data layer. */
type RichObject = Record<string, unknown>;
type ReferenceKind = "entries" | "assets";
type ReferenceSlot = "hyperlink" | "block" | "inline";
type ReferenceCache = Record<ReferenceKind, Map<string, RichObject>>;
type PendingReference = {
  field: RichObject;
  kind: ReferenceKind;
  slot: ReferenceSlot;
  id: string;
};

export type RichTextQueries = Partial<Record<ReferenceKind, string>>;
export type RichTextQuery = (
  document: string,
  variables: Record<string, unknown>,
) => Promise<unknown>;

const BATCH_SIZE = 10;
const MAX_PASSES = 8;
const MAX_NEW_REFERENCES_PER_KIND = 1000;
const REFERENCE_KINDS: Record<string, [ReferenceKind, ReferenceSlot]> = {
  "entry-hyperlink": ["entries", "hyperlink"],
  "embedded-entry-block": ["entries", "block"],
  "embedded-entry-inline": ["entries", "inline"],
  "asset-hyperlink": ["assets", "hyperlink"],
  "embedded-asset-block": ["assets", "block"],
};

function asObject(value: unknown): RichObject | undefined {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as RichObject)
    : undefined;
}

function containsReference(values: unknown, id: string): boolean {
  return (
    Array.isArray(values) &&
    values.some((item) => asObject(asObject(item)?.sys)?.id === id)
  );
}

/** Inspect document IDs, then recurse through already loaded entry data. */
function collectPendingReferences(data: unknown): PendingReference[] {
  const pending: PendingReference[] = [];

  function scan(value: unknown): void {
    if (Array.isArray(value)) {
      value.forEach(scan);
      return;
    }
    const field = asObject(value);
    if (!field) return;
    const document = asObject(field.json);

    function walk(node: unknown): void {
      const item = asObject(node);
      if (!item) return;
      const target = asObject(asObject(item.data)?.target);
      const sys = asObject(target?.sys);
      if (sys?.urn) {
        throw new Error(
          "Cross-space rich text resources require a configured resource resolver.",
        );
      }
      const shape = REFERENCE_KINDS[String(item.nodeType)];
      if (typeof sys?.id === "string" && shape) {
        const [kind, slot] = shape;
        const values = asObject(asObject(field!.links)?.[kind])?.[slot];
        if (!containsReference(values, sys.id)) {
          pending.push({ field: field!, kind, slot, id: sys.id });
        }
      }
      if (Array.isArray(item.content)) item.content.forEach(walk);
    }

    if (document) walk(document);
    // JSON nodes were handled above; only linked data can contain more documents.
    for (const [key, child] of Object.entries(field)) {
      if (key !== "json") scan(child);
    }
  }

  scan(data);
  return pending;
}

/** Undo query aliases that distinguish conflicting field types across CMS models. */
function normalizeEntryFields(item: RichObject): RichObject {
  const prefix = `foundry_${item.__typename}_`;
  return Object.fromEntries(
    Object.entries(item).map(([key, value]) => [
      key.startsWith(prefix) ? key.slice(prefix.length) : key,
      value,
    ]),
  );
}

async function fetchMissingReferences(
  kind: ReferenceKind,
  pending: PendingReference[],
  cache: ReferenceCache,
  queries: RichTextQueries,
  query: RichTextQuery,
): Promise<void> {
  const ids = [
    ...new Set(
      pending
        .filter(
          (reference) =>
            reference.kind === kind && !cache[kind].has(reference.id),
        )
        .map((reference) => reference.id),
    ),
  ];
  if (ids.length > MAX_NEW_REFERENCES_PER_KIND) {
    throw new Error("Rich text reference count exceeds the safe page limit.");
  }

  for (let start = 0; start < ids.length; start += BATCH_SIZE) {
    const batch = ids.slice(start, start + BATCH_SIZE);
    const document = queries[kind];
    if (!document)
      throw new Error(`Delivery schema cannot resolve rich text ${kind}.`);

    const result = asObject(await query(document, { ids: batch }));
    const collection = asObject(
      result?.[kind === "entries" ? "entryCollection" : "assetCollection"],
    );
    if (!Array.isArray(collection?.items)) {
      throw new Error(
        "Rich text reference lookup returned an invalid collection.",
      );
    }
    for (const value of collection.items) {
      const item = asObject(value);
      const id = asObject(item?.sys)?.id;
      if (item && typeof id === "string" && batch.includes(id)) {
        cache[kind].set(id, normalizeEntryFields(item));
      }
    }
    if (batch.some((id) => !cache[kind].has(id))) {
      throw new Error(
        "A rich text reference could not be resolved. Check that its target is published and accessible.",
      );
    }
  }
}

/** Each field receives its own copy so resolving nested documents stays local. */
function attachReferences(
  pending: PendingReference[],
  cache: ReferenceCache,
): void {
  for (const { field, kind, slot, id } of pending) {
    const links = asObject(field.links) ?? ((field.links = {}) as RichObject);
    const group = asObject(links[kind]) ?? ((links[kind] = {}) as RichObject);
    const values = Array.isArray(group[slot])
      ? (group[slot] as unknown[])
      : ((group[slot] = []) as unknown[]);
    if (!containsReference(values, id)) {
      values.push(structuredClone(cache[kind].get(id)!));
    }
  }
}

/**
 * Resolve only IDs used by rich-text documents, in bounded requests.
 * Populates the existing RichText renderer's links shape before normalization.
 * Cache lifetime is this call; missing references and recursive embeds fail.
 */
export async function resolveRichTextLinks(
  data: unknown,
  queries: RichTextQueries,
  query: RichTextQuery,
): Promise<void> {
  const cache: ReferenceCache = { entries: new Map(), assets: new Map() };
  for (let pass = 0; pass < MAX_PASSES; pass++) {
    const pending = collectPendingReferences(data);
    if (!pending.length) return;
    await fetchMissingReferences("entries", pending, cache, queries, query);
    await fetchMissingReferences("assets", pending, cache, queries, query);
    attachReferences(pending, cache);
  }
  throw new Error(
    "Rich text embeds exceed the supported reference depth or contain a cycle.",
  );
}

export { RICH_TEXT_QUERIES } from "./by-id/rich-text";

